WITH flattened AS (SELECT id, effective_from, currency, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_prices) e AS element) SELECT currency, DATE_TRUNC('WEEK', effective_from) AS week_start, ROUND(SUM(element) / NULLIF(COUNT(CASE WHEN currency = 'USD' THEN 1 END), 0), 2) AS element_per_usd, ROUND(SUM(element) / NULLIF(COUNT(CASE WHEN currency = 'USD' THEN 1 END), 0), 2) AS element_per_usd_2, MAX(element) AS max_element, COUNT(*) FILTER (WHERE currency = 'USD') AS usd_rows FROM flattened GROUP BY currency, DATE_TRUNC('WEEK', effective_from) ORDER BY usd_rows DESC NULLS LAST
